'use client';

import * as React from 'react';
import { createPortal } from 'react-dom';
import type { Transition } from 'motion/react';

import { mergeRefs } from './sidebar-animated-anchored';
import { IconSwap } from './sidebar-animated-icon-swap';
import {
  TriggerHighlightScope,
  useTriggerHighlight,
} from './sidebar-animated-item-highlight';
import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from './sidebar-animated-motion';
import {
  runCollapse,
  snapshotCollapse,
  stopCollapse,
  type CollapseSnapshot,
  type CollapseTimings,
} from './sidebar-animated-collapse';

const SIDEBAR_COOKIE_NAME = 'sidebar_state';
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
const SIDEBAR_KEYBOARD_SHORTCUT = 'b';
const MOBILE_BREAKPOINT = 768;

const COLLAPSE_TRANSITION: Transition = motionTokens.transition.collapse;
const LABEL_TRANSITION: Transition = motionTokens.transition.collapseLabel;
const COLOR_TRANSITION: Transition = motionTokens.transition.color;

const SIDEBAR_STYLE = {
  href: 'animate-ui-sidebar',
  css: [
    '[data-sidebar="menu-button"]{transition-duration:var(--animate-ui-sidebar-duration,280ms);transition-timing-function:var(--animate-ui-sidebar-easing,cubic-bezier(0.77,0,0.175,1))}',
    '[data-sidebar="group-label"]{transition-property:margin;transition-duration:var(--animate-ui-sidebar-duration,280ms);transition-timing-function:var(--animate-ui-sidebar-easing,cubic-bezier(0.77,0,0.175,1))}',
    '[data-sidebar="rail"],[data-sidebar="rail"]::after{transition-duration:var(--animate-ui-sidebar-color-duration,200ms);transition-timing-function:var(--animate-ui-sidebar-color-easing,ease)}',
    '[data-sidebar="rail"]::after{transition-property:background-color}',
  ].join(''),
};

type SidebarContextProps = {
  state: 'expanded' | 'collapsed';
  open: boolean;
  setOpen: (open: boolean) => void;
  openMobile: boolean;
  setOpenMobile: (open: boolean) => void;
  isMobile: boolean;
  toggleSidebar: () => void;
};

const SidebarContext = React.createContext<SidebarContextProps | null>(null);

const AnimateOnHoverContext = React.createContext(true);

function useSidebar() {
  const context = React.use(SidebarContext);
  if (!context) {
    throw new Error('useSidebar must be used within a SidebarProvider.');
  }
  return context;
}

const MOBILE_QUERY = `(max-width: ${MOBILE_BREAKPOINT - 1}px)`;

function subscribeMobile(onChange: () => void) {
  const mql = window.matchMedia(MOBILE_QUERY);
  mql.addEventListener('change', onChange);
  return () => mql.removeEventListener('change', onChange);
}

function useIsMobile() {
  return React.useSyncExternalStore(
    subscribeMobile,
    () => window.matchMedia(MOBILE_QUERY).matches,
    () => false,
  );
}

type ProviderProps = React.ComponentProps<'div'> & {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  animateOnHover?: boolean;
};

function Provider({
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  animateOnHover = true,
  style,
  children,
  ...props
}: ProviderProps) {
  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = React.useState(false);

  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const open = openProp ?? uncontrolledOpen;
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === 'function' ? value(open) : value;
      if (openProp === undefined) setUncontrolledOpen(openState);
      onOpenChange?.(openState);

      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    },
    [onOpenChange, open, openProp],
  );

  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
  }, [isMobile, setOpen]);

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey) &&
        !(event.target as HTMLElement | null)?.closest?.(
          'input, textarea, select, [contenteditable]:not([contenteditable="false"])',
        )
      ) {
        event.preventDefault();
        toggleSidebar();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [toggleSidebar]);

  const state = open ? 'expanded' : 'collapsed';

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, toggleSidebar],
  );

  const color = toCssTiming(useTempoTransition(COLOR_TRANSITION));
  const reduce = useShouldReduceMotion();
  const collapse = toCssTiming(useTempoTransition(COLLAPSE_TRANSITION));

  return (
    <SidebarContext value={contextValue}>
      <AnimateOnHoverContext value={animateOnHover}>
        <style href={SIDEBAR_STYLE.href} precedence="animate-ui">
          {SIDEBAR_STYLE.css}
        </style>
        <div
          {...props}
          style={
            {
              '--animate-ui-sidebar-color-duration': `${color.duration}ms`,
              '--animate-ui-sidebar-color-easing': color.easing,
              '--animate-ui-sidebar-duration': `${reduce ? 0 : collapse.duration}ms`,
              '--animate-ui-sidebar-easing': collapse.easing,
              ...style,
            } as React.CSSProperties
          }
        >
          {children}
        </div>
      </AnimateOnHoverContext>
    </SidebarContext>
  );
}

function useCssTransition(
  transition: Transition,
  properties: string,
): React.CSSProperties {
  const reduce = useShouldReduceMotion();
  const { duration, easing } = toCssTiming(useTempoTransition(transition));
  return {
    transitionProperty: properties,
    transitionDuration: `${reduce ? 0 : duration}ms`,
    transitionTimingFunction: easing,
    transitionDelay: '0ms',
  };
}

type GapProps = React.ComponentProps<'div'> & {
  transition?: Transition;
};

function Gap({ transition = COLLAPSE_TRANSITION, style, ...props }: GapProps) {
  const timing = useCssTransition(transition, 'width');
  return <div {...props} style={{ ...timing, ...style }} />;
}

type ContainerProps = React.ComponentProps<'div'> & {
  transition?: Transition;
};

function Container({
  transition = COLLAPSE_TRANSITION,
  style,
  ...props
}: ContainerProps) {
  const timing = useCssTransition(transition, 'left, right, width');
  return <div {...props} style={{ ...timing, ...style }} />;
}

const ITEMS = '[data-sidebar="menu-button"], [data-sidebar="menu-sub-button"]';
const DISABLED = ':disabled, [aria-disabled="true"], [data-disabled]';
const SURFACE = '[data-slot="trigger-highlight"]';

const roots = new WeakSet<Element>();

type Item = {
  node: HTMLElement;
  host: HTMLElement;
  disabled: boolean;
  key: number;
};

const keys = new WeakMap<HTMLElement, number>();
let nextKey = 0;
function keyOf(node: HTMLElement) {
  let key = keys.get(node);
  if (key === undefined) keys.set(node, (key = nextKey++));
  return key;
}

function closestRoot(node: HTMLElement) {
  for (let el = node.parentElement; el; el = el.parentElement)
    if (roots.has(el)) return el;
  return null;
}

const own = (root: HTMLElement, selector: string) =>
  [...root.querySelectorAll<HTMLElement>(selector)].filter(
    (node) => closestRoot(node) === root,
  );

const sameItems = (a: readonly Item[], b: readonly Item[]) =>
  a.length === b.length &&
  a.every(
    (item, i) =>
      item.node === b[i]!.node &&
      item.host === b[i]!.host &&
      item.disabled === b[i]!.disabled,
  );

const onlySurfaces = (record: MutationRecord) =>
  record.type === 'childList' &&
  [...record.addedNodes, ...record.removedNodes].every(
    (node) => node instanceof Element && node.matches(SURFACE),
  );

function useContentChanges(root: HTMLElement | null, onChange: () => void) {
  const onChangeRef = React.useRef(onChange);
  React.useLayoutEffect(() => {
    onChangeRef.current = onChange;
  });
  React.useLayoutEffect(() => {
    if (!root) return;
    onChangeRef.current();
    const observer = new MutationObserver((records) => {
      if (!records.every(onlySurfaces)) onChangeRef.current();
    });
    observer.observe(root, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: [
        'data-sidebar',
        'disabled',
        'aria-disabled',
        'data-disabled',
      ],
    });
    return () => observer.disconnect();
  }, [root]);
}

const NO_ITEMS: readonly Item[] = [];

function useItems(root: HTMLElement | null) {
  const [items, setItems] = React.useState<readonly Item[]>([]);
  useContentChanges(root, () => {
    const found: Item[] = [];
    for (const node of own(root!, ITEMS)) {
      const host = node.parentElement;
      if (!host) continue;
      found.push({
        node,
        host,
        disabled: node.matches(DISABLED),
        key: keyOf(node),
      });
    }
    setItems((current) => (sameItems(current, found) ? current : found));
  });
  return root ? items : NO_ITEMS;
}

type CollapseMotionProps = {
  root: HTMLElement | null;
  state: string | undefined;
  timings: CollapseTimings;
};

class CollapseMotion extends React.Component<CollapseMotionProps> {
  getSnapshotBeforeUpdate(previous: CollapseMotionProps) {
    const { root, state } = this.props;
    if (!root || previous.state === state || previous.state === undefined)
      return null;
    return snapshotCollapse(root);
  }

  componentDidUpdate(
    _: CollapseMotionProps,
    __: unknown,
    snapshot: CollapseSnapshot | null,
  ) {
    const { root, timings } = this.props;
    if (root && snapshot) runCollapse(root, snapshot, timings);
  }

  componentWillUnmount() {
    if (this.props.root) stopCollapse(this.props.root);
  }

  render() {
    return null;
  }
}

function ItemSurface({ node, host, disabled }: Omit<Item, 'key'>) {
  const { ref, highlight } = useTriggerHighlight(disabled, { beside: true });
  React.useLayoutEffect(() => ref(node), [ref, node]);
  return highlight ? createPortal(highlight, host) : null;
}

type HighlightProps = React.ComponentProps<'div'> & {
  animateOnHover?: boolean;
};

function Highlight({
  animateOnHover,
  ref,
  style,
  children,
  ...props
}: HighlightProps) {
  const inherited = React.use(AnimateOnHoverContext);
  const sidebar = React.use(SidebarContext);
  const enabled = animateOnHover ?? inherited;
  const [root, setRoot] = React.useState<HTMLDivElement | null>(null);
  const setRootRef = React.useCallback((node: HTMLDivElement | null) => {
    if (node) roots.add(node);
    setRoot(node);
  }, []);
  const mergedRef = React.useMemo(
    () => mergeRefs(ref, setRootRef),
    [ref, setRootRef],
  );
  const items = useItems(enabled ? root : null);

  const reduce = useShouldReduceMotion();
  const collapse = toCssTiming(useTempoTransition(COLLAPSE_TRANSITION));
  const label = toCssTiming(useTempoTransition(LABEL_TRANSITION));
  const duration = reduce ? 0 : collapse.duration;
  const timings = React.useMemo<CollapseTimings>(
    () => ({
      duration,
      easing: collapse.easing,
      labelDuration: label.duration,
      labelEasing: label.easing,
      blur: motionTokens.blur.icon,
      reduce,
    }),
    [duration, collapse.easing, label.duration, label.easing, reduce],
  );

  return (
    <div
      {...props}
      ref={mergedRef}
      style={enabled ? { isolation: 'isolate', ...style } : style}
    >
      <TriggerHighlightScope>
        {children}
        {items.map(({ key, ...item }) => (
          <ItemSurface key={key} {...item} />
        ))}
      </TriggerHighlightScope>
      <CollapseMotion root={root} state={sidebar?.state} timings={timings} />
    </div>
  );
}

type TriggerIconProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  open: React.ReactNode;
  closed: React.ReactNode;
  transition?: Transition;
};

function TriggerIcon({ open, closed, ...props }: TriggerIconProps) {
  const { state, isMobile, openMobile } = useSidebar();
  const isOpen = isMobile ? openMobile : state === 'expanded';
  return (
    <IconSwap swapKey={isOpen ? 'open' : 'closed'} {...props}>
      {isOpen ? open : closed}
    </IconSwap>
  );
}

export {
  Provider,
  Gap,
  Container,
  Highlight,
  TriggerIcon,
  useSidebar,
  type ProviderProps,
  type GapProps,
  type ContainerProps,
  type HighlightProps,
  type TriggerIconProps,
  type SidebarContextProps,
};

'use client';

import * as React from 'react';
import {
  motion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';

import {
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from './sidebar-animated-motion';
import { useStaggeredEnter } from './sidebar-animated-stagger';

const POPOVER_TRANSITION = motionTokens.spring.pop;
const MENU_TRANSITION = motionTokens.transition.menu;
const MORPH_TRANSITION = motionTokens.spring.morph;

const HIDDEN_SCALE = {
  tooltip: motionTokens.scale.tooltip,
  popover: motionTokens.scale.popover,
  menu: motionTokens.scale.menu,
} as const;
const DEFAULT_TRANSITION = {
  tooltip: POPOVER_TRANSITION,
  popover: POPOVER_TRANSITION,
  menu: MENU_TRANSITION,
} as const;

type AnchoredKind = keyof typeof HIDDEN_SCALE;

type AnchoredAnimationProps = {
  transition?: Transition;
  exitTransition?: Transition;
};

type AnchoredMotionOptions = AnchoredAnimationProps & {
  kind?: AnchoredKind;
  open: boolean;
  keepMounted?: boolean;
  instant?: boolean;
};

type AnchoredMotionProps = {
  initial: false | TargetAndTransition;
  animate: TargetAndTransition;
  exit: TargetAndTransition;
  style?: React.CSSProperties;
  onAnimationComplete?: (definition: unknown) => void;
};

const WARM_WINDOW = 300;

const tooltipGroup = {
  open: new Set<symbol>(),
  warm: false,
  coolDown: undefined as ReturnType<typeof setTimeout> | undefined,
  leaving: new Map<symbol, () => void>(),
};

function useWarmTooltip(open: boolean, enabled: boolean) {
  const [id] = React.useState(() => Symbol('tooltip'));
  const [change, setChange] = React.useState(() => ({
    open,
    atOnce: enabled && open && tooltipGroup.warm,
  }));
  if (change.open !== open) {
    setChange({
      open,
      atOnce:
        enabled &&
        (open
          ? tooltipGroup.warm
          : [...tooltipGroup.open].some((other) => other !== id)),
    });
  }
  const [cut, setCut] = React.useState(false);
  if (open && cut) setCut(false);
  const atOnceRef = React.useRef(change.atOnce);
  React.useLayoutEffect(() => {
    atOnceRef.current = change.atOnce;
  });

  React.useEffect(() => {
    if (!enabled || !open) return;
    tooltipGroup.open.add(id);
    tooltipGroup.warm = true;
    clearTimeout(tooltipGroup.coolDown);
    if (atOnceRef.current)
      for (const hide of tooltipGroup.leaving.values()) hide();
    return () => {
      tooltipGroup.open.delete(id);
      if (tooltipGroup.open.size > 0) return;
      clearTimeout(tooltipGroup.coolDown);
      tooltipGroup.coolDown = setTimeout(() => {
        tooltipGroup.warm = false;
      }, WARM_WINDOW);
    };
  }, [enabled, open, id]);

  React.useEffect(() => {
    if (!enabled || open) return;
    tooltipGroup.leaving.set(id, () => setCut(true));
    return () => {
      tooltipGroup.leaving.delete(id);
    };
  }, [enabled, open, id]);

  return {
    appearAtOnce: open && change.atOnce,
    hideAtOnce: !open && (change.atOnce || cut),
  };
}

function useAnchoredMotion({
  kind = 'popover',
  open,
  keepMounted,
  instant,
  transition,
  exitTransition,
}: AnchoredMotionOptions): AnchoredMotionProps {
  const reduce = useShouldReduceMotion();
  const warmsUp = kind === 'tooltip' && instant === undefined;
  const warm = useWarmTooltip(open, warmsUp);
  const enter = useTempoTransition(transition ?? DEFAULT_TRANSITION[kind]);
  const leave = useTempoTransition(
    exitTransition ?? transition ?? DEFAULT_TRANSITION[kind],
  );
  const quick = useStaggeredEnter(enter);
  const hidden = { opacity: 0, scale: reduce ? 1 : HIDDEN_SCALE[kind] };
  const shown = { opacity: 1, scale: 1 };
  const none = { duration: 0 };

  const [settledClosed, setSettledClosed] = React.useState(
    Boolean(keepMounted) && !open,
  );
  if (open && settledClosed) setSettledClosed(false);

  const appearAtOnce = instant || warm.appearAtOnce;

  return {
    initial: appearAtOnce || !open ? false : hidden,
    animate: open
      ? {
          ...shown,
          transition: appearAtOnce ? none : kind === 'menu' ? quick : enter,
          ...(keepMounted && { visibility: 'visible' }),
        }
      : {
          ...hidden,
          transition: instant ? none : leave,
          ...(keepMounted && settledClosed && { visibility: 'hidden' }),
        },
    exit: { ...hidden, transition: instant ? none : leave },
    style: warm.hideAtOnce ? { visibility: 'hidden' } : undefined,
    onAnimationComplete: keepMounted
      ? (definition) => {
          const target = definition as { opacity?: number };
          if (!open && target.opacity === 0) setSettledClosed(true);
        }
      : undefined,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyComponent = string | React.ComponentType<any>;
const motionComponents = new Map<AnyComponent, AnyComponent>();

function motionFor(type: AnyComponent): AnyComponent {
  let component = motionComponents.get(type);
  if (!component) {
    component =
      typeof type === 'string'
        ? (motion as unknown as Record<string, AnyComponent>)[type]!
        : (motion.create(type) as AnyComponent);
    motionComponents.set(type, component);
  }
  return component;
}

function mergeRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node);
      else if (ref) (ref as React.RefObject<T | null>).current = node;
    }
  };
}

type ElementProps = {
  ref?: React.Ref<HTMLElement>;
  style?: React.CSSProperties;
} & Record<string, unknown>;

function asMotion(element: React.ReactElement, props: ElementProps) {
  const own = element.props as ElementProps;
  const Component = motionFor(
    element.type as AnyComponent,
  ) as React.ElementType;
  return (
    <Component
      {...own}
      {...props}
      ref={mergeRefs(own.ref, props.ref)}
      style={{ ...own.style, ...props.style }}
    />
  );
}

export {
  useAnchoredMotion,
  asMotion,
  mergeRefs,
  POPOVER_TRANSITION,
  MENU_TRANSITION,
  MORPH_TRANSITION,
  HIDDEN_SCALE,
  type AnchoredKind,
  type AnchoredAnimationProps,
  type AnchoredMotionProps,
};

'use client';

import * as React from 'react';
import { AnimatePresence, motion, type Transition } from 'motion/react';

import {
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from './sidebar-animated-motion';

const SWAP_TRANSITION: Transition = motionTokens.transition.swap;

const HIDDEN = {
  opacity: 0,
  scale: motionTokens.scale.icon,
  filter: motionTokens.blur.icon,
};
const SHOWN = { opacity: 1, scale: 1, filter: 'blur(0px)' };

type IconSwapProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  swapKey: string;
  children: React.ReactNode;
  instant?: boolean;
  rotate?: number;
  transition?: Transition;
};

function IconSwap({
  swapKey,
  children,
  instant = false,
  rotate,
  transition,
  style,
  ...props
}: IconSwapProps) {
  const reduce = useShouldReduceMotion();
  const defaultTransition = useTempoTransition(
    rotate ? motionTokens.transition.spin : SWAP_TRANSITION,
  );
  const turn = reduce || !rotate ? undefined : rotate;
  const entering = reduce
    ? { opacity: 0, filter: HIDDEN.filter }
    : turn
      ? { ...HIDDEN, rotate: -turn }
      : HIDDEN;
  const leaving = reduce
    ? { opacity: 0, filter: HIDDEN.filter }
    : turn
      ? { ...HIDDEN, rotate: turn }
      : HIDDEN;
  const shown = reduce
    ? { opacity: 1, filter: SHOWN.filter }
    : turn
      ? { ...SHOWN, rotate: 0 }
      : SHOWN;

  return (
    <span
      style={{
        position: 'relative',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        ...style,
      }}
      {...props}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={swapKey}
          data-icon={swapKey}
          aria-hidden="true"
          initial={instant ? false : entering}
          animate={shown}
          exit={instant ? undefined : leaving}
          transition={transition ?? defaultTransition}
          style={{ display: 'inline-flex' }}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export { IconSwap, type IconSwapProps };

'use client';

import * as React from 'react';
import {
  createGeneratorEasing,
  generateLinearEasing,
  spring as springGenerator,
  type Transition,
} from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from './sidebar-animated-motion';
import { layoutScale } from './sidebar-animated-layout-scale';
import { staggerLeft } from './sidebar-animated-stagger';

const HIGHLIGHT_TRANSITION = motionTokens.spring.highlight;
const FADE_TRANSITION = motionTokens.transition.color;
const RESUME_TRANSITION = motionTokens.transition.fade;

type Surface = {
  backgroundColor: string;
  backgroundImage: string;
  borderRadius: string;
};

type Offset = {
  x: number;
  y: number;
  scaleX: number;
  scaleY: number;
};

type Glide = {
  animation: Animation;
  ease: (progress: number) => number;
  duration: number;
  from: Offset;
};

type SurfaceHandle = {
  id: string;
  element: HTMLElement;
  item: HTMLElement;
  glide: Glide | null;
};

type Leaving = { id: string; to: HTMLElement | null; key: number };

type HighlightScopeValue = {
  activeId: string | null;
  leaving: readonly Leaving[];
  slot: string;
  activate: (id: string, item: HTMLElement) => void;
  light: (id: string, item: HTMLElement) => void;
  unlight: (id: string) => void;
  left: (id: string) => void;
  handOff: (item: HTMLElement, reduce: boolean, fading?: boolean) => Start;
  register: (handle: SurfaceHandle) => () => void;
  carry: (handle: SurfaceHandle) => () => void;
  gone: (opacity: number) => void;
  paint: (surface: Surface) => Surface;
};

const HighlightScopeContext = React.createContext<HighlightScopeValue | null>(
  null,
);

const TriggerScopeContext = React.createContext<HighlightScopeValue | null>(
  null,
);

type HighlightScopeProps = {
  open: boolean;
  shared?: boolean;
  children?: React.ReactNode;
};

function HighlightScope({ shared, ...props }: HighlightScopeProps) {
  const parent = React.use(HighlightScopeContext);
  if (shared && parent) return props.children;
  return (
    <OwnHighlightScope
      {...props}
      context={HighlightScopeContext}
      slot="item-highlight"
    />
  );
}

function TriggerHighlightScope({ children }: { children?: React.ReactNode }) {
  return (
    <OwnHighlightScope
      open
      context={TriggerScopeContext}
      slot="trigger-highlight"
    >
      {children}
    </OwnHighlightScope>
  );
}

function OwnHighlightScope({
  open,
  context: Context,
  slot,
  children,
}: Omit<HighlightScopeProps, 'shared'> & {
  context: React.Context<HighlightScopeValue | null>;
  slot: string;
}) {
  const [activeId, setActiveId] = React.useState<string | null>(null);
  const [leaving, setLeaving] = React.useState<readonly Leaving[]>([]);
  const surfaceRef = React.useRef<SurfaceHandle | null>(null);
  const carriersRef = React.useRef(new Set<SurfaceHandle>());
  const keyRef = React.useRef(0);
  const paintRef = React.useRef<Surface | null>(null);
  const litRef = React.useRef(new Map<string, HTMLElement>());
  const activeRef = React.useRef<string | null>(null);
  React.useLayoutEffect(() => {
    activeRef.current = activeId;
  }, [activeId]);
  const [wasOpen, setWasOpen] = React.useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (open) {
      setActiveId(null);
      setLeaving([]);
    }
  }

  const activate = React.useCallback((id: string, item: HTMLElement) => {
    const previous = surfaceRef.current;
    activeRef.current = id;
    setActiveId(id);
    const moves =
      previous && previous.id !== id && previous.element.isConnected
        ? previous
        : null;
    const cross = moves !== null && crossesClip(moves.item, item);
    const key = (keyRef.current += 1);
    setLeaving((list) => {
      const rest = without(list, id).filter((other) => other.to !== null);
      if (!moves || (!cross && rest.length === 0)) return rest;
      const along = rest.map((other) => ({ ...other, to: item, key }));
      return cross
        ? [...without(along, moves.id), { id: moves.id, to: item, key }]
        : along;
    });
  }, []);
  const left = React.useCallback(
    (id: string) => setLeaving((list) => without(list, id)),
    [],
  );
  const light = React.useCallback(
    (id: string, item: HTMLElement) => {
      litRef.current.delete(id);
      litRef.current.set(id, item);
      activate(id, item);
    },
    [activate],
  );
  const unlight = React.useCallback(
    (id: string) => {
      const lit = litRef.current;
      const item = lit.get(id);
      if (!lit.delete(id) || activeRef.current !== id) return;
      const next = [...lit].at(-1);
      if (next) {
        activate(...next);
        return;
      }
      activeRef.current = null;
      setActiveId(null);
      const key = (keyRef.current += 1);
      // The copies carrying it there end in the one fading out
      setLeaving((list) => [
        ...without(list, id).filter((other) => other.to !== item),
        { id, to: null, key },
      ]);
    },
    [activate],
  );
  const goneRef = React.useRef<{ opacity: number; at: number } | null>(null);
  const handOffFrom = React.useCallback(
    (item: HTMLElement, reduce: boolean, fading = false) => {
      const from = fading
        ? mostShown(surfaceRef.current, carriersRef.current)
        : surfaceRef.current;
      const start = handOff(from, item, reduce);
      const gone = goneRef.current;
      if (
        !from?.element.isConnected &&
        gone &&
        performance.now() - gone.at < 120
      )
        return { ...start, opacity: gone.opacity, fresh: false };
      return start;
    },
    [],
  );
  const gone = React.useCallback((opacity: number) => {
    goneRef.current = { opacity, at: performance.now() };
  }, []);
  const carry = React.useCallback((handle: SurfaceHandle) => {
    carriersRef.current.add(handle);
    return () => {
      carriersRef.current.delete(handle);
    };
  }, []);
  const register = React.useCallback((handle: SurfaceHandle) => {
    surfaceRef.current = handle;
    return () => {
      if (surfaceRef.current === handle) surfaceRef.current = null;
    };
  }, []);
  const paint = React.useCallback((surface: Surface) => {
    if (isBare(surface)) return paintRef.current ?? surface;
    paintRef.current = surface;
    return surface;
  }, []);

  const value = React.useMemo(
    () => ({
      activeId,
      leaving,
      slot,
      activate,
      light,
      unlight,
      left,
      handOff: handOffFrom,
      register,
      carry,
      gone,
      paint,
    }),
    [
      activeId,
      leaving,
      slot,
      activate,
      light,
      unlight,
      left,
      handOffFrom,
      register,
      carry,
      gone,
      paint,
    ],
  );

  return <Context value={value}>{children}</Context>;
}

const SURFACE_PROPERTIES = ['background-color', 'background-image'] as const;
type SavedStyle = [property: string, value: string, priority: string][];
const savedStyles = new WeakMap<HTMLElement, SavedStyle>();

function save(node: HTMLElement, properties: readonly string[]): SavedStyle {
  return properties.map((property) => [
    property,
    node.style.getPropertyValue(property),
    node.style.getPropertyPriority(property),
  ]);
}

function restore(node: HTMLElement, saved: SavedStyle) {
  for (const [property, value, priority] of saved) {
    if (value) node.style.setProperty(property, value, priority);
    else node.style.removeProperty(property);
  }
}

function clearOwnSurface(node: HTMLElement, clear: boolean) {
  const saved = savedStyles.get(node);
  if (clear && !saved) {
    savedStyles.set(node, save(node, SURFACE_PROPERTIES));
    node.style.setProperty('background-color', 'transparent', 'important');
    node.style.setProperty('background-image', 'none', 'important');
  } else if (!clear && saved) {
    savedStyles.delete(node);
    restore(node, saved);
  }
}

const isBare = ({ backgroundColor, backgroundImage }: Surface) =>
  backgroundImage === 'none' &&
  (backgroundColor === 'transparent' ||
    /^rgba\(.*,\s*0\)$/.test(backgroundColor));

/** A surface painted in the color behind it shows nothing: a highlight may glide over it. */
function blendsIn(node: HTMLElement, surface: Surface) {
  if (surface.backgroundImage !== 'none' || isBare(surface)) return false;
  for (let el = node.parentElement; el; el = el.parentElement) {
    const style = getComputedStyle(el);
    if (style.backgroundImage !== 'none') return false;
    const backdrop = { ...surface, backgroundColor: style.backgroundColor };
    if (!isBare(backdrop))
      return style.backgroundColor === surface.backgroundColor;
  }
  return false;
}

function readSurface(node: HTMLElement): Surface {
  const cleared = savedStyles.get(node);
  // Only a transition on the background has to stop for it to be read: taking
  // the others off would cancel them (a sidebar button's width as it folds)
  const stops = /all|background/.test(
    getComputedStyle(node).transitionProperty,
  );
  const transition = stops ? save(node, ['transition']) : null;
  if (stops) node.style.setProperty('transition', 'none', 'important');
  if (cleared) restore(node, cleared);
  const style = getComputedStyle(node);
  const surface = {
    backgroundColor: style.backgroundColor,
    backgroundImage: style.backgroundImage,
    borderRadius: style.borderRadius,
  };
  if (cleared) {
    node.style.setProperty('background-color', 'transparent', 'important');
    node.style.setProperty('background-image', 'none', 'important');
  }
  void getComputedStyle(node).backgroundColor;
  if (transition) restore(node, transition);
  return surface;
}

const isExpanded = (node: HTMLElement) =>
  node.getAttribute('aria-expanded') === 'true';

const without = (list: readonly Leaving[], id: string) =>
  list.some((other) => other.id === id)
    ? list.filter((other) => other.id !== id)
    : list;

function clipperOf(item: HTMLElement) {
  const body = item.ownerDocument.body;
  for (let el = item.parentElement; el && el !== body; el = el.parentElement) {
    const { overflowX, overflowY } = getComputedStyle(el);
    if (overflowX !== 'visible' || overflowY !== 'visible') return el;
  }
  return null;
}

const crossesClip = (from: HTMLElement, to: HTMLElement) =>
  clipperOf(from) !== clipperOf(to);

// Out of a clipped box into the one around it, the one leaving is cut on the
// way: it fades out under the one coming in, whole at once. Otherwise the one
// coming in fades in over the one leaving.
const comesOut = (from: HTMLElement, to: HTMLElement) => {
  const inner = clipperOf(from);
  const outer = clipperOf(to);
  return !!inner && !inner.contains(to) && (!outer || outer.contains(from));
};

type ItemHighlight = {
  ref: (node: HTMLElement | null) => void;
  highlight: React.ReactNode;
};

type ItemHighlightOptions = {
  attribute?: string;
  followFocus?: boolean;
};

type TriggerHighlightOptions = {
  beside?: boolean;
};

function useItemHighlight(
  disabled?: boolean,
  {
    attribute = 'data-highlighted',
    followFocus = false,
  }: ItemHighlightOptions = {},
): ItemHighlight {
  return useHighlightIn(
    React.use(HighlightScopeContext),
    disabled,
    attribute,
    false,
    followFocus,
  );
}

function useTriggerHighlight(
  disabled?: boolean,
  { beside = false }: TriggerHighlightOptions = {},
): ItemHighlight {
  return useHighlightIn(React.use(TriggerScopeContext), disabled, null, beside);
}

const samePaint = (a: Surface | null, b: Surface) =>
  a !== null &&
  a.backgroundColor === b.backgroundColor &&
  a.backgroundImage === b.backgroundImage &&
  a.borderRadius === b.borderRadius;

const TRIGGER_ATTRIBUTES = [
  'aria-expanded',
  'data-state',
  'data-highlighted',
  'data-popup-open',
  'data-pressed',
  'data-disabled',
];

function useHighlightIn(
  scope: HighlightScopeValue | null,
  disabled: boolean | undefined,
  attribute: string | null,
  beside = false,
  followFocus = false,
): ItemHighlight {
  const id = React.useId();
  const [node, setNode] = React.useState<HTMLElement | null>(null);
  const [surface, setSurface] = React.useState<Surface | null>(null);
  const paint = scope?.paint;
  const light = scope?.light;
  const unlight = scope?.unlight;
  const ref = React.useCallback((element: HTMLElement | null) => {
    if (element)
      setNode((current) => (current === element ? current : element));
  }, []);

  React.useLayoutEffect(() => {
    if (attribute !== null || !light || !unlight || !node) return;
    if (!beside && getComputedStyle(node).position === 'static')
      node.style.setProperty('position', 'relative');
    let hovered = false;
    let lit = false;
    let frame = 0;
    const sync = () => {
      const interactive =
        !disabled && (hovered || isExpanded(node) || node.matches(':focus'));
      if (interactive) clearOwnSurface(node, true);
      const surface = interactive ? readSurface(node) : null;
      const now = surface !== null && !isBare(surface);
      if (surface && now)
        setSurface((current) =>
          samePaint(current, surface) ? current : surface,
        );
      clearOwnSurface(
        node,
        now || (!interactive && blendsIn(node, readSurface(node))),
      );
      if (now === lit) return;
      lit = now;
      if (now) light(id, node);
      else unlight(id);
    };
    const enter = () => {
      hovered = true;
      sync();
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(sync);
    };
    const leave = () => {
      hovered = false;
      cancelAnimationFrame(frame);
      sync();
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      attributes: true,
      attributeFilter: TRIGGER_ATTRIBUTES,
    });
    node.addEventListener('pointerenter', enter);
    node.addEventListener('pointerleave', leave);
    node.addEventListener('focus', sync);
    node.addEventListener('blur', sync);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      node.removeEventListener('pointerenter', enter);
      node.removeEventListener('pointerleave', leave);
      node.removeEventListener('focus', sync);
      node.removeEventListener('blur', sync);
      clearOwnSurface(node, false);
      if (lit) unlight(id);
    };
  }, [attribute, light, unlight, node, id, disabled, beside]);

  React.useLayoutEffect(() => {
    if (attribute === null || !light || !unlight || !paint || !node) return;
    if (getComputedStyle(node).position === 'static')
      node.style.setProperty('position', 'relative');

    const clear = () =>
      clearOwnSurface(
        node,
        node.hasAttribute(attribute) ||
          isExpanded(node) ||
          node.matches(':focus'),
      );
    const sync = () => {
      if (node.hasAttribute(attribute)) {
        setSurface(paint(readSurface(node)));
        light(id, node);
      } else if (followFocus) unlight(id);
      clear();
    };
    const focus = () => {
      if (node.hasAttribute(attribute)) setSurface(paint(readSurface(node)));
      clear();
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      attributes: true,
      attributeFilter: [attribute, 'aria-expanded'],
    });
    node.addEventListener('focus', focus);
    node.addEventListener('blur', clear);
    return () => {
      observer.disconnect();
      node.removeEventListener('focus', focus);
      node.removeEventListener('blur', clear);
      clearOwnSurface(node, false);
    };
  }, [light, unlight, paint, node, id, attribute, followFocus]);

  const active = scope?.activeId === id && !disabled;
  const leaving =
    (!disabled && scope?.leaving.find((other) => other.id === id)) || null;

  return {
    ref,
    highlight: scope ? (
      <HighlightSurface
        id={id}
        surface={surface}
        active={active}
        leaving={leaving}
        item={node}
        scope={scope}
        beside={beside}
      />
    ) : null,
  };
}

type HighlightSurfaceProps = {
  id: string;
  surface: Surface | null;
  active: boolean;
  leaving: Leaving | null;
  item: HTMLElement | null;
  scope: HighlightScopeValue;
  beside: boolean;
};

function HighlightSurface({
  id,
  surface,
  active,
  leaving,
  item,
  scope,
  beside,
}: HighlightSurfaceProps) {
  if (!surface || !item) return null;
  return (
    <>
      {active && (
        <SurfaceCopy
          key="active"
          id={id}
          surface={surface}
          item={item}
          scope={scope}
          beside={beside}
        />
      )}
      {leaving && !active && (
        <SurfaceCopy
          key={`leaving-${leaving.key}`}
          id={id}
          surface={surface}
          item={item}
          scope={scope}
          beside={beside}
          leavingTo={leaving.to}
          fadeOut={leaving.to === null}
        />
      )}
    </>
  );
}

function placeOver(element: HTMLElement, item: HTMLElement) {
  const host = element.offsetParent as HTMLElement | null;
  const box = item.getBoundingClientRect();
  const origin = host?.getBoundingClientRect();
  const { x: ratioX, y: ratioY } =
    host && origin ? layoutScale(host, origin) : { x: 1, y: 1 };
  const left = origin
    ? (box.left - origin.left) / ratioX - host!.clientLeft + host!.scrollLeft
    : box.left + window.scrollX;
  const top = origin
    ? (box.top - origin.top) / ratioY - host!.clientTop + host!.scrollTop
    : box.top + window.scrollY;
  element.style.left = `${left}px`;
  element.style.top = `${top}px`;
  element.style.width = `${box.width / ratioX}px`;
  element.style.height = `${box.height / ratioY}px`;
}

function useBesideBox(
  elementRef: React.RefObject<HTMLElement | null>,
  item: HTMLElement,
  beside: boolean,
) {
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!beside || !element) return;
    const place = () => placeOver(element, item);
    place();
    const observer = new ResizeObserver(place);
    observer.observe(item);
    if (element.offsetParent) observer.observe(element.offsetParent);
    return () => observer.disconnect();
  }, [elementRef, item, beside]);
}

type Start = {
  offset: Offset;
  opacity: number;
  color: string | null;
  fresh: boolean;
  velocity: Offset;
  cross: boolean;
  enters: boolean;
};

const IN_PLACE: Offset = { x: 0, y: 0, scaleX: 1, scaleY: 1 };
const STILL: Offset = { x: 0, y: 0, scaleX: 0, scaleY: 0 };

function velocityOf({ animation, ease, duration, from }: Glide): Offset {
  const time = Number(animation.currentTime ?? duration);
  if (!(time < duration)) return STILL;
  const step = 4;
  const before = Math.max(0, time - step);
  const rate =
    (ease(Math.min(1, (before + step) / duration)) - ease(before / duration)) /
    step;
  return {
    x: -from.x * rate,
    y: -from.y * rate,
    scaleX: (1 - from.scaleX) * rate,
    scaleY: (1 - from.scaleY) * rate,
  };
}

// Carried over from another clipped box, the highlight is shown by the copies
// leaving for it while it fades in: it fades out from the one shown most
function mostShown(
  surface: SurfaceHandle | null,
  carriers: Set<SurfaceHandle>,
) {
  let shown = surface?.element.isConnected ? surface : null;
  let most = shown ? Number(getComputedStyle(shown.element).opacity) : 0;
  for (const carrier of carriers) {
    if (!carrier.element.isConnected) continue;
    const opacity = Number(getComputedStyle(carrier.element).opacity);
    if (opacity > most) {
      shown = carrier;
      most = opacity;
    }
  }
  return shown ?? surface;
}

function handOff(
  previous: SurfaceHandle | null,
  item: HTMLElement,
  reduce: boolean,
): Start {
  if (!previous?.element.isConnected)
    return {
      offset: IN_PLACE,
      opacity: 0,
      color: null,
      fresh: true,
      velocity: STILL,
      cross: false,
      enters: false,
    };
  const style = getComputedStyle(previous.element);
  const opacity = Number(style.opacity);
  const color = style.backgroundColor;
  const cross = crossesClip(previous.item, item);
  const enters = cross && !comesOut(previous.item, item);
  const offset = offsetOn(previous.element.getBoundingClientRect(), item);
  if (reduce || !offset)
    return {
      offset: IN_PLACE,
      opacity,
      color,
      fresh: false,
      velocity: STILL,
      cross,
      enters,
    };

  const own = item.getBoundingClientRect();
  const from = previous.item.getBoundingClientRect();
  const velocity = previous.glide ? velocityOf(previous.glide) : STILL;
  return {
    offset,
    opacity,
    color,
    fresh: false,
    velocity: {
      x: velocity.x,
      y: velocity.y,
      scaleX: (velocity.scaleX * from.width) / own.width,
      scaleY: (velocity.scaleY * from.height) / own.height,
    },
    cross,
    enters,
  };
}

function offsetOn(box: DOMRect, item: HTMLElement): Offset | null {
  const own = item.getBoundingClientRect();
  if (!own.width || !own.height) return null;
  const ratioX = own.width / (item.offsetWidth || own.width);
  const ratioY = own.height / (item.offsetHeight || own.height);
  return {
    x: (box.left - own.left) / ratioX,
    y: (box.top - own.top) / ratioY,
    scaleX: box.width / own.width,
    scaleY: box.height / own.height,
  };
}

function initialRate(
  { offset, velocity }: Start,
  to: Offset,
  width: number,
  height: number,
) {
  const way = [
    to.x - offset.x,
    to.y - offset.y,
    (to.scaleX - offset.scaleX) * width,
    (to.scaleY - offset.scaleY) * height,
  ];
  const speed = [
    velocity.x,
    velocity.y,
    velocity.scaleX * width,
    velocity.scaleY * height,
  ];
  const length = way.reduce((sum, d) => sum + d * d, 0);
  if (length < 0.25) return null;
  return way.reduce((sum, d, i) => sum + d * speed[i]!, 0) / length;
}

const toTransform = ({ x, y, scaleX, scaleY }: Offset) =>
  `translate(${x}px, ${y}px) scale(${scaleX}, ${scaleY})`;

type SurfaceCopyProps = {
  id: string;
  surface: Surface;
  item: HTMLElement;
  scope: HighlightScopeValue;
  leavingTo?: HTMLElement | null;
  fadeOut?: boolean;
  beside?: boolean;
};

function SurfaceCopy({
  id,
  surface,
  item,
  scope,
  leavingTo = null,
  fadeOut = false,
  beside = false,
}: SurfaceCopyProps) {
  const reduce = useShouldReduceMotion();
  const glide = useTempoTransition<Transition>(HIGHLIGHT_TRANSITION);
  const fade = useTempoTransition<Transition>(FADE_TRANSITION);
  const resume = useTempoTransition<Transition>(RESUME_TRANSITION);
  const [start] = React.useState(() => scope.handOff(item, reduce, fadeOut));
  const [target] = React.useState(() =>
    leavingTo && !reduce
      ? offsetOn(leavingTo.getBoundingClientRect(), item)
      : null,
  );
  const elementRef = React.useRef<HTMLSpanElement>(null);
  const transitionsRef = React.useRef({ glide, fade, resume });
  const { register, carry, gone, left } = scope;
  useBesideBox(elementRef, item, beside);

  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!element) return undefined;
    const animations: Animation[] = [];
    let running: Glide | null = null;
    if (leavingTo && !target) {
      left(id);
      return undefined;
    }

    const to = target ?? IN_PLACE;
    const rate = initialRate(start, to, item.offsetWidth, item.offsetHeight);
    let timing: { duration: number; easing: string } | null = null;
    if (rate !== null) {
      const { ease, duration } = createGeneratorEasing(
        { ...transitionsRef.current.glide, velocity: rate * 1000 * 100 },
        100,
        springGenerator,
      );
      const ms = duration * 1000;
      timing = { duration: ms, easing: generateLinearEasing(ease, ms) };
      const animation = element.animate(
        [
          { transform: toTransform(start.offset) },
          { transform: target ? toTransform(target) : 'none' },
        ],
        { ...timing, fill: target ? 'forwards' : 'auto' },
      );
      animations.push(animation);
      running = { animation, ease, duration: ms, from: start.offset };
    }

    if (target) {
      if (running && comesOut(item, leavingTo!))
        animations.push(
          element.animate([{ opacity: 1 }, { opacity: 0 }], {
            ...timing!,
            fill: 'forwards',
          }),
        );
      if (running)
        running.animation.finished.then(
          () => left(id),
          () => {},
        );
      else left(id);
      const uncarry = carry({ id, element, item, glide: running });
      return () => {
        for (const animation of animations) animation.cancel();
        uncarry();
      };
    }

    // An item still coming in with its list's stagger: its highlight shows once it has landed.
    const landing = staggerLeft(element.parentElement);
    if (fadeOut) {
      const { duration, easing } = toCssTiming(transitionsRef.current.fade);
      const fading = element.animate(
        [{ opacity: start.opacity }, { opacity: 0 }],
        { duration, easing, fill: 'forwards' },
      );
      animations.push(fading);
      fading.finished.then(
        () => left(id),
        () => {},
      );
    } else if (start.enters && timing) {
      animations.push(
        element.animate([{ opacity: 0 }, { opacity: 1 }], timing),
      );
    } else if (start.opacity < 1 || landing > 0) {
      const { duration, easing } = toCssTiming(
        start.fresh || landing > 0
          ? transitionsRef.current.fade
          : transitionsRef.current.resume,
      );
      animations.push(
        element.animate(
          [{ opacity: landing > 0 ? 0 : start.opacity }, { opacity: 1 }],
          { duration, easing, delay: landing, fill: 'backwards' },
        ),
      );
    }

    const color = getComputedStyle(element).backgroundColor;
    if (start.color && start.color !== color && !target) {
      const { duration, easing } = toCssTiming(transitionsRef.current.fade);
      animations.push(
        element.animate(
          [{ backgroundColor: start.color }, { backgroundColor: color }],
          { duration, easing },
        ),
      );
    }

    const unregister = register({ id, element, item, glide: running });
    return () => {
      const opacity = element.isConnected
        ? Number(getComputedStyle(element).opacity)
        : 0;
      for (const animation of animations) animation.cancel();
      unregister();
      gone(opacity);
    };
  }, [
    register,
    carry,
    gone,
    left,
    id,
    item,
    start,
    target,
    leavingTo,
    fadeOut,
  ]);

  const { duration: colorDuration, easing: colorEasing } = toCssTiming(fade);

  return (
    <span
      ref={elementRef}
      aria-hidden
      data-slot={scope.slot}
      data-leaving={leavingTo || fadeOut ? '' : undefined}
      style={{
        position: 'absolute',
        ...(!beside && { inset: 0 }),
        zIndex: -1,
        pointerEvents: 'none',
        transformOrigin: '0 0',
        borderRadius: surface.borderRadius,
        backgroundColor: surface.backgroundColor,
        backgroundImage: surface.backgroundImage,
        transition: `background-color ${colorDuration}ms ${colorEasing}`,
      }}
    />
  );
}

function withHighlight(
  children: React.ReactNode,
  highlight: React.ReactNode,
  asChild?: boolean,
): React.ReactNode {
  if (!highlight) return children;
  if (asChild && React.isValidElement<{ children?: React.ReactNode }>(children))
    return React.cloneElement(
      children,
      undefined,
      <>
        {children.props.children}
        {highlight}
      </>,
    );
  return (
    <>
      {children}
      {highlight}
    </>
  );
}

