type Laid = {
  display: string;
  position: string;
  height: number;
  paddingTop: string;
  paddingBottom: string;
  marginTop: string;
  marginBottom: string;
};

type CollapseSnapshot = {
  mode: string;
  shown: Map<HTMLElement, Laid>;
};

type CollapseTimings = {
  duration: number;
  easing: string;
  labelDuration: number;
  labelEasing: string;
  blur: string;
  reduce: boolean;
};

const PARTS = '[data-sidebar]';
const BUTTONS = '[data-sidebar="menu-button"]';
const GROUP_LABELS = '[data-sidebar="group-label"]';

const modeOf = (root: HTMLElement) =>
  root.closest('[data-collapsible]')?.getAttribute('data-collapsible') ?? null;

function laidOut(element: HTMLElement): Laid {
  const style = getComputedStyle(element);
  return {
    display: style.display,
    position: style.position,
    height: element.getBoundingClientRect().height,
    paddingTop: style.paddingTop,
    paddingBottom: style.paddingBottom,
    marginTop: style.marginTop,
    marginBottom: style.marginBottom,
  };
}

function snapshotCollapse(root: HTMLElement): CollapseSnapshot | null {
  const mode = modeOf(root);
  if (mode === null) return null;
  const shown = new Map<HTMLElement, Laid>();
  for (const element of root.querySelectorAll<HTMLElement>(PARTS)) {
    const laid = laidOut(element);
    if (laid.display !== 'none') shown.set(element, laid);
  }
  return { mode, shown };
}

type Running = {
  animations: Animation[];
  restore: () => void;
  kept: Set<HTMLElement>;
};

const running = new WeakMap<HTMLElement, Running>();

function stopCollapse(root: HTMLElement) {
  const current = running.get(root);
  const shown = new Map<HTMLElement, { opacity: number; height: number }>();
  if (!current) return { shown, kept: new Set<HTMLElement>() };
  const moved = new Set(
    current.animations.flatMap((animation) => {
      const target = (animation.effect as KeyframeEffect | null)?.target;
      return target instanceof HTMLElement ? [target] : [];
    }),
  );
  for (const element of moved)
    shown.set(element, {
      opacity: Number(getComputedStyle(element).opacity),
      height: element.getBoundingClientRect().height,
    });
  for (const animation of current.animations) animation.cancel();
  current.restore();
  running.delete(root);
  return { shown, kept: current.kept };
}

function labelsOf(root: HTMLElement) {
  const labels: HTMLElement[] = [
    ...root.querySelectorAll<HTMLElement>(GROUP_LABELS),
  ];
  for (const button of root.querySelectorAll<HTMLElement>(BUTTONS)) {
    const children = [...button.children] as HTMLElement[];
    const [first] = children;
    const leadingIcon =
      first &&
      (first.matches('svg, img, [data-slot="avatar"]') ||
        !first.textContent?.trim());
    labels.push(...(leadingIcon ? children.slice(1) : children));
  }
  return labels;
}

function runCollapse(
  root: HTMLElement,
  before: CollapseSnapshot,
  timings: CollapseTimings,
) {
  const mode = modeOf(root);
  const collapsing = mode === 'icon' && before.mode !== 'icon';
  const expanding = before.mode === 'icon' && mode !== 'icon' && mode !== null;
  const interrupted = stopCollapse(root);
  if (!collapsing && !expanding) return;

  const { duration, easing, labelDuration, labelEasing, reduce } = timings;
  const blurred = { filter: timings.blur };
  const sharp = { filter: 'blur(0px)' };
  const labelDelay = expanding && !reduce ? duration - labelDuration : 0;
  const animations: Animation[] = [];
  const restores: (() => void)[] = [];
  const kept = new Set<HTMLElement>();

  const setInline = (
    element: HTMLElement,
    property: string,
    value: string,
    priority = '',
  ) => {
    const previous = element.style.getPropertyValue(property);
    const previousPriority = element.style.getPropertyPriority(property);
    element.style.setProperty(property, value, priority);
    restores.push(() => {
      if (previous)
        element.style.setProperty(property, previous, previousPriority);
      else element.style.removeProperty(property);
    });
  };

  const fade = (element: HTMLElement, fill: FillMode) => {
    const from = interrupted.shown.get(element)?.opacity;
    animations.push(
      element.animate(
        collapsing
          ? [
              { opacity: from ?? 1, ...sharp },
              { opacity: 0, ...blurred },
            ]
          : [
              { opacity: from ?? 0, ...blurred },
              { opacity: 1, ...sharp },
            ],
        {
          duration: labelDuration,
          easing: labelEasing,
          delay: labelDelay,
          fill,
        },
      ),
    );
  };

  const hidden: HTMLElement[] = [];
  const shown: HTMLElement[] = [];
  for (const element of root.querySelectorAll<HTMLElement>(PARTS)) {
    const display = getComputedStyle(element).display;
    const was = before.shown.get(element);
    if (collapsing && was && display === 'none') hidden.push(element);
    else if (
      expanding &&
      display !== 'none' &&
      (!was || interrupted.kept.has(element))
    )
      shown.push(element);
  }
  const outermost = (list: HTMLElement[]) =>
    list.filter(
      (element) =>
        !list.some((other) => other !== element && other.contains(element)),
    );

  if (!reduce) {
    for (const element of hidden) {
      setInline(
        element,
        'display',
        before.shown.get(element)!.display,
        'important',
      );
      kept.add(element);
    }
    for (const element of outermost(hidden)) {
      const laid = before.shown.get(element)!;
      fade(element, 'forwards');
      if (laid.position === 'absolute' || laid.position === 'fixed') continue;
      setInline(element, 'overflow', 'hidden');
      animations.push(
        element.animate(
          [
            {
              height: `${interrupted.shown.get(element)?.height ?? laid.height}px`,
              paddingTop: laid.paddingTop,
              paddingBottom: laid.paddingBottom,
              marginTop: laid.marginTop,
              marginBottom: laid.marginBottom,
            },
            {
              height: '0px',
              paddingTop: '0px',
              paddingBottom: '0px',
              marginTop: '0px',
              marginBottom: '0px',
            },
          ],
          { duration, easing, fill: 'forwards' },
        ),
      );
    }
    for (const element of outermost(shown)) {
      const laid = laidOut(element);
      fade(element, 'backwards');
      if (laid.position === 'absolute' || laid.position === 'fixed') continue;
      const from = interrupted.shown.get(element)?.height ?? 0;
      setInline(element, 'overflow', 'hidden');
      animations.push(
        element.animate(
          [
            {
              height: `${from}px`,
              ...(from === 0 && {
                paddingTop: '0px',
                paddingBottom: '0px',
                marginTop: '0px',
                marginBottom: '0px',
              }),
            },
            {
              height: `${laid.height}px`,
              paddingTop: laid.paddingTop,
              paddingBottom: laid.paddingBottom,
              marginTop: laid.marginTop,
              marginBottom: laid.marginBottom,
            },
          ],
          { duration, easing, fill: 'backwards' },
        ),
      );
    }
  }

  for (const label of labelsOf(root)) {
    if (reduce || ![...hidden, ...shown].some((part) => part.contains(label)))
      fade(label, collapsing ? 'forwards' : 'backwards');
    for (const element of [label, ...label.querySelectorAll<HTMLElement>('*')])
      if (getComputedStyle(element).textOverflow === 'ellipsis')
        setInline(element, 'text-overflow', 'clip');
  }

  const persistent = collapsing
    ? animations.filter((animation) => {
        const target = (animation.effect as KeyframeEffect | null)?.target;
        return target instanceof HTMLElement && !kept.has(target);
      })
    : [];
  const transient = animations.filter((a) => !persistent.includes(a));
  const restore = () => {
    for (const undo of restores.splice(0).reverse()) undo();
  };
  const state: Running = { animations, restore, kept };
  running.set(root, state);
  void Promise.all(transient.map((animation) => animation.finished))
    .then(() =>
      transient.length
        ? undefined
        : new Promise((resolve) => setTimeout(resolve, duration)),
    )
    .then(() => {
      if (running.get(root) !== state) return;
      for (const animation of transient) animation.cancel();
      restore();
      state.animations = persistent;
      state.kept = new Set();
      state.restore = () => {};
    })
    .catch(() => {});
}

export {
  snapshotCollapse,
  runCollapse,
  stopCollapse,
  type CollapseSnapshot,
  type CollapseTimings,
};

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from './sidebar-animated-motion';

const ROWS = [
  '[role^="menuitem"]',
  '[role="option"]',
  '[role="separator"]',
  '[data-slot$="-label"]',
  '[data-slot="navigation-menu-link"]',
  '[data-slot="sidebar-menu-sub-item"]',
].join(',');

const STAGGER = { duration: 0.3, ease: motionTokens.ease.soft, delay: 0.033 };
const SHIFT = 8;
const ARRIVE = { duration: 0.1, ease: motionTokens.ease.out };
const CALM = 10;
const STAGGER_ID = 'animate-ui-stagger';

type StaggerTiming = { duration: number; easing: string; step: number };

function opacityOf(el: Element) {
  let opacity = 1;
  for (let node: Element | null = el; node; node = node.parentElement)
    opacity *= Number(getComputedStyle(node).opacity);
  return opacity;
}

function rowsOf(root: HTMLElement) {
  const rows = [...root.querySelectorAll<HTMLElement>(ROWS)].filter(
    (row) => !row.closest('[data-animate-ui-handoff]'),
  );
  return rows.filter(
    (row) => !rows.some((other) => other !== row && other.contains(row)),
  );
}

function animateRows(rows: HTMLElement[], timing: StaggerTiming) {
  const shift =
    rows[0] && getComputedStyle(rows[0]).direction === 'rtl' ? -SHIFT : SHIFT;
  const step =
    rows.length > CALM
      ? timing.step * Math.sqrt(CALM / rows.length)
      : timing.step;
  return rows.map((row, index) =>
    row.animate(
      [
        {
          opacity: 0,
          filter: motionTokens.blur.surface,
          translate: `${shift}px 0`,
        },
        // No opacity here: it ends on the row's own, a disabled one's 50% or one the library shows late.
        { filter: 'blur(0px)', translate: '0 0' },
      ],
      {
        duration: timing.duration,
        easing: timing.easing,
        delay: index * step,
        fill: 'backwards',
        id: STAGGER_ID,
      },
    ),
  );
}

/** How long until `row` lands from its stagger (0 when it isn't staggering). */
function staggerLeft(row: Element | null) {
  const animation = row
    ?.getAnimations()
    .find((candidate) => candidate.id === STAGGER_ID);
  if (!animation || animation.playState === 'finished') return 0;
  const end = animation.effect?.getComputedTiming().endTime;
  return Math.max(0, Number(end ?? 0) - Number(animation.currentTime ?? 0));
}

/**
 * A just-opened list's rows slide in from the side one after another, out of a blur;
 * rows a library renders a commit later (React Aria's) as they come, before
 * they're painted. `stop` shows them all.
 */
/**
 * Rows slid aside widen what their list can scroll: a library scrolling the
 * chosen one into view (Base UI's combobox) would scroll sideways too, then
 * back as they land. The lists keep their horizontal scroll meanwhile.
 */
function holdScrollX(root: HTMLElement) {
  const lefts = new Map<Element, number>();
  for (const el of [root, ...root.querySelectorAll('*')])
    lefts.set(el, el.scrollLeft);
  const hold = (event: Event) => {
    const target = event.target as Element;
    const left = lefts.get(target);
    if (left !== undefined && target.scrollLeft !== left)
      target.scrollLeft = left;
  };
  root.addEventListener('scroll', hold, true);
  return () => root.removeEventListener('scroll', hold, true);
}

function staggerRows(root: HTMLElement, timing: StaggerTiming) {
  let animations: Animation[] = [];
  let observer: MutationObserver | null = null;
  const release = holdScrollX(root);
  const start = (rows: HTMLElement[]) => {
    animations = animateRows(rows, timing);
    void Promise.all(animations.map((animation) => animation.finished)).then(
      release,
      release,
    );
  };
  const rows = rowsOf(root);
  if (rows.length) start(rows);
  else {
    observer = new MutationObserver(() => {
      const late = rowsOf(root);
      if (!late.length) return;
      observer?.disconnect();
      observer = null;
      start(late);
    });
    observer.observe(root, { childList: true, subtree: true });
    setTimeout(() => {
      if (!observer) return;
      observer.disconnect();
      release();
    }, 300);
  }
  return () => {
    observer?.disconnect();
    for (const animation of animations) animation.finish();
    release();
  };
}

/** Staggers `el`'s rows if it opens from closed: it's still transparent. */
function staggerFromClosed(el: HTMLElement, timing: StaggerTiming) {
  return opacityOf(el) > 0.05 ? null : staggerRows(el, timing);
}

function useStaggerTiming() {
  const transition = useTempoTransition(STAGGER);
  const timingRef = React.useRef<StaggerTiming>(null!);
  React.useLayoutEffect(() => {
    timingRef.current = {
      ...toCssTiming(transition),
      step: (transition.delay ?? 0) * 1000,
    };
  });
  return timingRef;
}

/**
 * Staggers the rows of `ref`'s list as it opens from closed (it starts
 * transparent, or `fresh` says so), not as it comes back while closing or
 * takes over another menu's popover.
 */
function useStaggerOnOpen(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
  options: {
    skip?: boolean;
    fresh?: boolean | ((el: HTMLElement) => boolean);
    closed?: (el: HTMLElement) => boolean;
  } = {},
) {
  const reduce = useShouldReduceMotion();
  const timingRef = useStaggerTiming();
  const {
    skip = false,
    fresh,
    closed = (el) => opacityOf(el) <= 0.05,
  } = options;
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!open || reduce || skip || !el) return;
    const opening =
      typeof fresh === 'function' ? fresh(el) : (fresh ?? closed(el));
    if (!opening) return;
    return staggerRows(el, timingRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);
}

/** A sidebar's submenu, in a collapsible panel: its sub-items stagger as it unfolds from closed. */
function useSubmenuStagger(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
) {
  useStaggerOnOpen(ref, open, {
    closed: (el) =>
      el.offsetHeight < 1 &&
      !!el.querySelector('[data-slot="sidebar-menu-sub"]'),
  });
}

/** A list whose rows stagger: its box is there at once (opacity), its rows bring the fade; under reduced motion, nothing staggers and it fades. */
function useStaggeredEnter(enter: Transition): Transition {
  const reduce = useShouldReduceMotion();
  const arrive = useTempoTransition(ARRIVE);
  return reduce ? enter : { ...enter, opacity: arrive };
}

/**
 * A sidebar submenu's panel is there at once (opacity, blur) while it unfolds,
 * so its sub-items bring the fade: added over the panel's own animation, after it starts.
 */
function quickSubmenuPanel(el: HTMLElement | null) {
  if (!el?.querySelector('[data-slot="sidebar-menu-sub"]')) return;
  queueMicrotask(() => {
    const ends = el
      .getAnimations()
      .map((animation) =>
        Number(animation.effect?.getComputedTiming().endTime ?? 0),
      );
    const total = Math.max(300, ...ends);
    const settled = { opacity: 1, filter: 'blur(0px)' };
    el.animate(
      [
        { ...settled, offset: Math.min(1, 100 / total) },
        { ...settled, offset: 1 },
      ],
      { duration: total, easing: 'ease-out' },
    );
  });
}

/**
 * Whether a list just mounted has been painted once: its first open lays it
 * out before the next paint, long enough for a fade started at mount to be
 * over unseen, so it opens from then.
 */
function usePainted() {
  const [painted, setPainted] = React.useState(false);
  React.useLayoutEffect(() => {
    const frame = requestAnimationFrame(() => setPainted(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  return painted;
}

export {
  quickSubmenuPanel,
  staggerFromClosed,
  useStaggeredEnter,
  staggerLeft,
  useSubmenuStagger,
  staggerRows,
  useStaggerOnOpen,
  useStaggerTiming,
  usePainted,
  type StaggerTiming,
};

/**
 * How much transforms scale `el` on screen. Divides by its exact layout size:
 * offsetWidth is rounded, so a box of fractional size would read as scaled.
 */
export function layoutScale(
  el: HTMLElement,
  rect = el.getBoundingClientRect(),
) {
  const style = getComputedStyle(el);
  const sum = (...names: string[]) =>
    style.boxSizing === 'border-box'
      ? 0
      : names.reduce(
          (total, name) =>
            total + (parseFloat(style.getPropertyValue(name)) || 0),
          0,
        );
  const width =
    parseFloat(style.width) +
      sum(
        'padding-left',
        'padding-right',
        'border-left-width',
        'border-right-width',
      ) || el.offsetWidth;
  const height =
    parseFloat(style.height) +
      sum(
        'padding-top',
        'padding-bottom',
        'border-top-width',
        'border-bottom-width',
      ) || el.offsetHeight;
  return {
    x: width ? rect.width / width : 1,
    y: height ? rect.height / height : 1,
  };
}
